#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int dung = 0;
    for (int i = 0; i < n; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        if (a == b) dung++;
    }
    int pct = (dung * 100) / n;
    if (pct >= 80) printf("dat %d\n", pct);
    else printf("chua dat %d\n", pct);
    return 0;
}
